"use client";

import { useState } from "react";
import { useRouter, useParams } from "next/navigation";
import { BookingDetail } from "@/shared/types/booking";

// ─── 목업 데이터 ──────────────────────────────────────────────────────────────
const MOCK_BOOKING: Pick<BookingDetail, "orderId" | "show"> = {
  orderId: "TRV-2026-031501",
  show: {
    title: "뮤지컬 <슬립노모어>",
    venue: "블랙박스씨어터",
    address: "서울 송파구 올림픽로 240",
    date: "2026.01.25",
    time: "오후 7:00-9:30",
    seat: "VIP석 2인",
  },
};

// ─── 상수 ─────────────────────────────────────────────────────────────────────
const APPEAL_POINTS = ["무대연출", "스토리", "배우연기", "안무", "넘버"] as const;
const EMOTION_POINTS = ["몰입감", "긴장감", "즐거움", "카타르시스", "감동"] as const;

// ─── 서브 컴포넌트 ─────────────────────────────────────────────────────────────
function TagButton({
  label,
  selected,
  onClick,
}: {
  label: string;
  selected: boolean;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className={`rounded-md border px-4 py-1.5 text-[14px] font-medium transition-colors ${
        selected
          ? "border-[#FB7079] bg-[#FFF5F6] text-[#F11322]"
          : "border-[#B9B9C6] text-[#23222A] hover:border-[#9E9DAF]"
      }`}
    >
      {label}
    </button>
  );
}

// ─── 메인 컴포넌트 ─────────────────────────────────────────────────────────────
export default function ReviewPage() {
  const router = useRouter();
  const params = useParams();
  const orderId = params.orderId as string;

  const booking = MOCK_BOOKING;

  const [liked, setLiked] = useState<boolean | null>(null);
  const [selectedAppeal, setSelectedAppeal] = useState<Set<string>>(new Set());
  const [selectedEmotion, setSelectedEmotion] = useState<Set<string>>(new Set());
  const [reviewText, setReviewText] = useState("");

  const toggleTag = (
    set: Set<string>,
    setFn: React.Dispatch<React.SetStateAction<Set<string>>>,
    value: string
  ) => {
    const next = new Set(set);
    if (next.has(value)) {
      next.delete(value);
    } else {
      next.add(value);
    }
    setFn(next);
  };

  const canSubmit = liked !== null;

  const handleSubmit = async () => {
    if (!canSubmit) return;

    // TODO: 백엔드 연동 시 API 호출
    // await reviewService.post({
    //   orderId,
    //   liked,
    //   appealPoints: Array.from(selectedAppeal),
    //   emotionPoints: Array.from(selectedEmotion),
    //   content: reviewText,
    // });

    console.log("관람평 제출:", {
      orderId,
      liked,
      appealPoints: Array.from(selectedAppeal),
      emotionPoints: Array.from(selectedEmotion),
      content: reviewText,
    });

    const reviewed = JSON.parse(localStorage.getItem("reviewedOrders") ?? "[]");
    reviewed.push(orderId);
    localStorage.setItem("reviewedOrders", JSON.stringify(reviewed));

    router.push("/mypage/bookings");
  };

  return (
    <div className="flex-1 py-10 bg-white min-h-screen pl-20">
      <div className="max-w-4xl mx-auto px-4">

        <h1 className="text-[32px] font-bold text-[#23222A] mb-8">관람평</h1>

        {/* 공연 정보 카드 */}
        <div className="rounded-xl border border-[#DDDDE4] bg-white p-4 mb-6">
            <div className="flex gap-4 items-start">
                {/* 포스터 placeholder */}
                <div className="h-[111px] w-[83px] shrink-0 rounded-md overflow-hidden flex items-center justify-center bg-[#F4F4F6]">
                {/* SVG placeholder */}
                    <svg width="100%" height="100%" viewBox="0 0 200 267" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink" preserveAspectRatio="xMidYMid meet">
                    <path d="M0 8C0 3.58172 3.58172 0 8 0H192C196.418 0 200 3.58172 200 8V259C200 263.418 196.418 267 192 267H8C3.58173 267 0 263.418 0 259V8Z" fill="url(#pattern0_563_7124)"/>
                    <defs>
                    <pattern id="pattern0_563_7124" patternContentUnits="objectBoundingBox" width="1" height="1">
                    <use xlinkHref="#image0_563_7124" transform="matrix(0.001335 0 0 0.001 -0.000625 0)"/>
                    </pattern>
                    <image id="image0_563_7124" width="750" height="1000" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
                    </defs>
                    </svg>
                </div>
                <div className="flex-1 flex flex-col">
                <p className="text-[16px] font-bold text-[#23222A]">{booking.show.title} 어땠나요?</p>
                <p className="text-[13px] text-[#68677E]">{booking.show.date}</p>
                {/* 좋아요/별로예요 버튼 */}
                <div className="flex gap-3 mt-8">
                    <button
                    onClick={() => setLiked(true)}
                    className={`flex-1 rounded-md border py-1 text-[14px] font-semibold transition-colors ${
                        liked === true
                        ? "border-[#FB7079] bg-[#FFF5F6] text-[#F11322]"
                        : "border-[#B9B9C6] text-[#23222A] hover:border-[#9E9DAF]"
                    }`}
                    >
                    좋았어요
                    </button>
                    <button
                    onClick={() => setLiked(false)}
                    className={`flex-1 rounded-md border py-1 text-[14px] font-semibold transition-colors ${
                        liked === false
                        ? "border-[#FB7079] bg-[#FFF5F6] text-[#F11322]"
                        : "border-[#B9B9C6] text-[#23222A] hover:border-[#9E9DAF]"
                    }`}
                    >
                    별로예요
                    </button>
                </div>
                </div>
            </div>
        </div>

        {/* 매력 포인트 */}
        <div className="mb-6">
          <p className="text-[16px] font-bold text-[#23222A] mb-1">
            매력 포인트 <span className="text-[16px] font-medium text-[#9E9DAF]">(복수선택 가능)</span>
          </p>
          <div className="flex flex-wrap gap-2 mt-3">
            {APPEAL_POINTS.map((point) => (
              <TagButton
                key={point}
                label={point}
                selected={selectedAppeal.has(point)}
                onClick={() => toggleTag(selectedAppeal, setSelectedAppeal, point)}
              />
            ))}
          </div>
        </div>

        {/* 감정 포인트 */}
        <div className="mb-6">
          <p className="text-[16px] font-bold text-[#23222A] mb-1">
            감정 포인트 <span className="text-[16px] font-medium text-[#9E9DAF]">(복수선택 가능)</span>
          </p>
          <div className="flex flex-wrap gap-2 mt-3">
            {EMOTION_POINTS.map((point) => (
              <TagButton
                key={point}
                label={point}
                selected={selectedEmotion.has(point)}
                onClick={() => toggleTag(selectedEmotion, setSelectedEmotion, point)}
              />
            ))}
          </div>
        </div>

        {/* 나의 관람평 */}
        <div className="mb-8">
          <p className="text-[16px] font-bold text-[#23222A] mb-3">나의 관람평</p>
          <textarea
            value={reviewText}
            onChange={(e) => setReviewText(e.target.value)}
            placeholder="관람평 작성하기"
            className="w-full rounded-md border border-[#DDDDE4] px-4 py-3 text-[14px] text-[#23222A] placeholder:text-[#9E9DAF] outline-none focus:border-[#FB7079] transition-colors resize-none h-[120px]"
          />
        </div>

        {/* 게시하기 버튼 */}
        <div className="flex justify-end">
          <button
            onClick={handleSubmit}
            disabled={!canSubmit}
            className={`px-12 py-2 rounded-md text-[16px] font-semibold transition-colors ${
              canSubmit
                ? "bg-[#23222A] text-white hover:bg-[#3a3945]"
                : "bg-[#DDDDE4] text-white cursor-not-allowed"
            }`}
          >
            게시하기
          </button>
        </div>

      </div>
    </div>
  );
}